let cps_number_strip : (int) list =
  (cps "uzyslLUnIN")

let rec clean_number__left (n : int) (strip : (int -> bool)) (i : int) : int =
  (if (((<) i n) && (strip i)) then ((clean_number__left n strip) ((+) i 1)) else i)

let rec clean_number__right (strip : (int -> bool)) (j : int) : int =
  (if (((>) j 0) && (strip ((-) j 1))) then ((clean_number__right strip) ((-) j 1)) else j)

let clean_number (s : string) : string =
  (let n = (String.length s) in
  let strip = (fun i -> (mem_cp ((fun s i -> if i >= 0 && i < String.length s then Char.code (String.unsafe_get s i) else -1) s i) cps_number_strip)) in
  let tmp = ((clean_number__left n strip) 0) in
  let tmp1 = ((clean_number__right strip) n) in
  ((fun s i j -> let n = String.length s in let i = if i > 0 then i else 0 and j = if j < n then j else n in if j <= i then "" else String.sub s i (j - i)) s tmp tmp1))

let rec maybe_trim_lines__aux (k : int) (s : string) (j : int) (i : int) : int =
  (if ((>) i j) then k else (if ((<>) ((fun s i -> if i >= 0 && i < String.length s then Char.code (String.unsafe_get s i) else -1) s i) (FStarC_SmallInt.of_char 32)) then i else ((maybe_trim_lines__aux k s j) ((+) i 1))))

let maybe_trim_lines (start_column : int) (comment_ : string) : string =
  (if ((=) start_column 0) then comment_ else (let lines = (FStarC_String.split (10 :: []) comment_) in
  let ensures_empty_prefix = (fun k s -> (let j = (FStarC_SmallInt.min k ((-) (String.length s) 1)) in
    ((maybe_trim_lines__aux k s j) 0))) in
  let trim_width = (BatList.fold_left ensures_empty_prefix start_column lines) in
  let tail = (fun s -> (let n = (String.length s) in
    (if ((>=) trim_width n) then "" else ((fun s i j -> let n = String.length s in let i = if i > 0 then i else 0 and j = if j < n then j else n in if j <= i then "" else String.sub s i (j - i)) s trim_width n)))) in
  let tmp = (BatList.map tail lines) in
  (BatString.concat "\n" tmp)))

let add_comment (st : lstate) (s : string) (r : FStarC_Range_Type.range) : unit =
  (let tmp = (!((st).comments)) in
  let tmp1 = ((s, r) :: tmp) in
  (((st).comments) := tmp1);
  let tmp2 = (!((st).ncomments)) in
  let tmp3 = ((+) tmp2 1) in
  (((st).ncomments) := tmp3))

let comment_stop (c : int) : bool =
  ((((=) c (FStarC_SmallInt.of_char 40)) || ((=) c (FStarC_SmallInt.of_char 42))) || (is_newline_char c))

let rec comment (st : lstate) (inner : bool) (buf : ((string) list ref)) (startpos : Prims.int) (startcol : int) : unit =
  (let i = (!((st).cur)) in
  let terminate = (fun tmp -> (let endpos = (cur_pos st) in
    let tmp1 = (!(buf)) in
    let tmp2 = ("*)" :: tmp1) in
    let s = (chunks_to_string tmp2) in
    ((buf) := []);
    let tmp3 = (maybe_trim_lines startcol s) in
    (add_comment st tmp3 (mk_range st startpos endpos)))) in
  let j = (run_end st comment_stop i) in
  (if ((>) j i) then (let tmp = (!(buf)) in
  let tmp1 = ((lexeme st i j) :: tmp) in
  ((buf) := tmp1);
  (((st).cur) := j);
  (comment st inner buf startpos startcol)) else (let c = (byte st i) in
  (if (((=) c (FStarC_SmallInt.of_char 40)) && ((=) (byte st ((+) i 1)) (FStarC_SmallInt.of_char 42))) then (let tmp = (!(buf)) in
  let tmp1 = ("(*" :: tmp) in
  ((buf) := tmp1);
  (((st).cur) := ((+) i (FStarC_SmallInt.of_int (Prims.of_int (2)))));
  (comment st true buf startpos startcol);
  (comment st inner buf startpos startcol)) else (let nl = (match_newline st i) in
  (if ((>=) nl 0) then ((((st).cur) := nl);
  (new_line st);
  let tmp = (!(buf)) in
  let tmp1 = ((lexeme st i nl) :: tmp) in
  ((buf) := tmp1);
  (comment st inner buf startpos startcol)) else (if (((=) c (FStarC_SmallInt.of_char 42)) && ((=) (byte st ((+) i 1)) (FStarC_SmallInt.of_char 41))) then ((((st).cur) := ((+) i (FStarC_SmallInt.of_int (Prims.of_int (2)))));
  (terminate ())) else (if ((>=) i (st).len) then (terminate ()) else (let j1 = (next st i) in
  let tmp = (!(buf)) in
  let tmp1 = ((lexeme st i j1) :: tmp) in
  ((buf) := tmp1);
  (((st).cur) := j1);
  (comment st inner buf startpos startcol))))))))))

let line_comment (st : lstate) (pre : string) : unit =
  (let i = (!((st).cur)) in
  let j = (run_end st is_newline_char i) in
  let sp = (pos_of st i) in
  let ep = (pos_of st j) in
  (((st).cur) := j);
  (add_comment st (Prims.strcat pre (lexeme st i j)) (mk_range st sp ep)))

let string_stop (c : int) : bool =
  ((((=) c (FStarC_SmallInt.of_char 92)) || ((=) c (FStarC_SmallInt.of_char 34))) || (is_newline_char c))

let string_of_cp (c : int) : string =
  ((fun l -> let b = BatUTF8.Buf.create 16 in List.iter (fun c -> BatUTF8.Buf.add_char b (BatUChar.chr c)) l; BatUTF8.Buf.contents b) ((Z.to_int (Z.of_int c)) :: []))

let rec string_lit (st : lstate) (acc : (string) list) (sp : Prims.int) : token =
  (let i = (!((st).cur)) in
  let j = (run_end st string_stop i) in
  (if ((>) j i) then ((((st).cur) := j);
  (string_lit st ((lexeme st i j) :: acc) sp)) else (let c = (get st i) in
  let nl1 = (if ((=) c (FStarC_SmallInt.of_char 92)) then (match_newline st ((+) i 1)) else (-1)) in
  (if ((>=) nl1 0) then (let tmp = (star st is_anywhite nl1) in
  (((st).cur) := tmp);
  (new_line st);
  (string_lit st acc sp)) else (let nl = (match_newline st i) in
  (if ((>=) nl 0) then ((((st).cur) := nl);
  (new_line st);
  (string_lit st ((lexeme st i nl) :: acc) sp)) else (let esc = (match_escape st i) in
  (if ((>=) esc 0) then ((((st).cur) := esc);
  let tmp = (unescape st i) in
  let tmp1 = (string_of_cp tmp) in
  let tmp2 = (tmp1 :: acc) in
  (string_lit st tmp2 sp)) else (if ((=) c (FStarC_SmallInt.of_char 34)) then ((((st).cur) := ((+) i 1));
  let tmp = (chunks_to_string acc) in
  let tmp1 = (cur_pos st) in
  let tmp2 = (!((st).ncomments)) in
  (tok FStarC_Parser_TokenKind.STRING tmp sp tmp1 tmp2)) else (if ((<) c 0) then (let tmp = (cur_pos st) in
  let tmp1 = (cur_pos st) in
  (lex_error st FStarC_Errors_Codes.Fatal_SyntaxError "unterminated string" tmp tmp1)) else ((((st).cur) := ((+) i 1));
  (string_lit st ((lexeme st i ((+) i 1)) :: acc) sp))))))))))))

