let rec next_token (st : lstate) : token =
  (let i = (!((st).cur)) in
  let sp = (cur_pos st) in
  (if ((>=) i (st).len) then (let tmp = (!((st).ncomments)) in
  (tok FStarC_Parser_TokenKind.EOF "" sp sp tmp)) else (let tmp = (select st i) in
  (match tmp with
    | (r, e) -> (let finish = (fun k txt -> ((((st).cur) := e);
        let tmp1 = (cur_pos st) in
        let tmp2 = (!((st).ncomments)) in
        (tok k txt sp tmp1 tmp2))) in
      let s = (fun tmp1 -> (lexeme st i e)) in
      (match r with
        | (REarly (k)) -> (finish k "")
        | RTripleBacktick -> (let name = (lexeme st ((+) i (FStarC_SmallInt.of_int (Prims.of_int (3)))) e) in
          (((st).cur) := e);
          let pos = (cur_pos st) in
          (blob st [] name pos sp))
        | RLang -> (let name = (lexeme st ((+) i (FStarC_SmallInt.of_int (Prims.of_int (6)))) e) in
          (((st).cur) := e);
          let pos = (cur_pos st) in
          (use_lang st [] name pos sp))
        | RSourceFile -> (finish FStarC_Parser_TokenKind.STRING (FStarC_Filepath.basename (st).fname))
        | RLine -> (let tmp1 = (!((st).lnum)) in
          let tmp2 = (string_of_int tmp1) in
          (finish FStarC_Parser_TokenKind.INT tmp2))
        | RFileLine -> (let tmp1 = (!((st).lnum)) in
          let tmp2 = (string_of_int tmp1) in
          let tmp3 = (Prims.strcat tmp2 ")") in
          let tmp4 = (Prims.strcat "(" tmp3) in
          let tmp5 = (Prims.strcat (FStarC_Filepath.basename (st).fname) tmp4) in
          (finish FStarC_Parser_TokenKind.STRING tmp5))
        | RWhite -> ((((st).cur) := e);
          (next_token st))
        | RNewline -> ((((st).cur) := e);
          (new_line st);
          (next_token st))
        | RCharLit -> (let c = (unescape st ((+) i 1)) in
          let t = (finish FStarC_Parser_TokenKind.CHAR "") in
          { kind = (t).kind;
            text = (t).text;
            sp = (t).sp;
            ep = (t).ep;
            extra = (CharLit ((Z.of_int c)));
            ncom = (t).ncom })
        | RCharLitB -> (let c = (unescape st ((+) i 1)) in
          let t = (finish FStarC_Parser_TokenKind.CHAR "") in
          { kind = (t).kind;
            text = (t).text;
            sp = (t).sp;
            ep = (t).ep;
            extra = (CharLit ((Z.of_int c)));
            ncom = (t).ncom })
        | RBacktick -> (finish FStarC_Parser_TokenKind.BACKTICK "")
        | (RKwOp (n, k, kop)) -> (let e' = (no_comment st i e) in
          (((st).cur) := e');
          let rest = (lexeme st ((+) i n) e') in
          let ep = (cur_pos st) in
          (if ((=) rest "") then (let tmp1 = (!((st).ncomments)) in
          (tok k "" sp ep tmp1)) else (let tmp1 = (!((st).ncomments)) in
          (tok kop rest sp ep tmp1))))
        | RSemiSemi -> (finish FStarC_Parser_TokenKind.SEMICOLON_OP "")
        | RIdent -> (let id = (s ()) in
          (if (FStarC_Util.starts_with id FStarC_Ident.reserved_prefix) then (let tmp1 = (pos_of st e) in
          (lex_error st FStarC_Errors_Codes.Fatal_ReservedPrefix (Prims.strcat FStarC_Ident.reserved_prefix " is a reserved prefix for an identifier") sp tmp1)) else (match (FStarC_PSMap.try_find keywords id) with
            | (Some ((k, ""))) -> (finish k "")
            | (Some ((k, t))) -> (finish k t)
            | None -> (finish FStarC_Parser_TokenKind.IDENT id)
          )))
        | RConstructor -> (let id = (s ()) in
          (match (FStarC_PSMap.try_find constructors id) with
            | (Some ((k, t))) -> (finish k t)
            | None -> (finish FStarC_Parser_TokenKind.NAME id)
          ))
        | RInt -> (let tmp1 = (s ()) in
          let tmp2 = (clean_number tmp1) in
          (finish FStarC_Parser_TokenKind.INT tmp2))
        | RUInt8 -> (let tmp1 = (s ()) in
          let c = (clean_number tmp1) in
          let cv = (Z.of_string c) in
          (if ((Prims.op_Less cv Prims.int_zero) || (Prims.op_Greater cv (Prims.of_int (255)))) then (let tmp2 = (pos_of st e) in
          (lex_error st FStarC_Errors_Codes.Fatal_SyntaxError "Out-of-range character literal" sp tmp2)) else (finish FStarC_Parser_TokenKind.UINT8 c)))
        | (RNumber (k)) -> (let tmp1 = (s ()) in
          let tmp2 = (clean_number tmp1) in
          (finish k tmp2))
        | RReal -> (finish FStarC_Parser_TokenKind.REAL (lexeme st i ((-) e 1)))
        | RBadNumber -> (let tmp1 = (s ()) in
          let tmp2 = (Prims.strcat "This is not a valid numeric literal: " tmp1) in
          let tmp3 = (pos_of st e) in
          (lex_error st FStarC_Errors_Codes.Fatal_SyntaxError tmp2 sp tmp3))
        | RCommentStart -> (let startcol = (col_of st i) in
          (((st).cur) := e);
          let buf = (ref ("(*" :: [])) in
          (comment st false buf sp startcol);
          (next_token st))
        | RInFStar -> ((((st).cur) := e);
          (next_token st))
        | RLineComment -> ((((st).cur) := e);
          let tmp1 = (s ()) in
          (line_comment st tmp1);
          (next_token st))
        | RString -> ((((st).cur) := e);
          (string_lit st [] sp))
        | RBacktickIdent -> (finish FStarC_Parser_TokenKind.IDENT (lexeme st ((+) i (FStarC_SmallInt.of_int (Prims.of_int (2)))) ((-) e (FStarC_SmallInt.of_int (Prims.of_int (2))))))
        | RPipeLeft -> (finish FStarC_Parser_TokenKind.PIPE_LEFT "")
        | RPipeRight -> (finish FStarC_Parser_TokenKind.PIPE_RIGHT "")
        | RDotDot -> (finish FStarC_Parser_TokenKind.DOT_DOT "")
        | (ROpToken (k, t)) -> (finish k t)
        | RLt -> (finish FStarC_Parser_TokenKind.OPINFIX0c "<")
        | RGt -> (let e' = (no_comment st ((+) i 1) e) in
          (((st).cur) := e');
          let tmp1 = (pos_of st ((+) i 1)) in
          let tmp2 = (cur_pos st) in
          let tmp3 = (!((st).ncomments)) in
          (tok FStarC_Parser_TokenKind.OPINFIX0c (Prims.strcat ">" (lexeme st ((+) i 1) e')) tmp1 tmp2 tmp3))
        | (ROp (k)) -> (let e' = (no_comment st i e) in
          (if ((=) e' i) then ((line_comment st "");
          (next_token st)) else ((((st).cur) := e');
          let tmp1 = (cur_pos st) in
          let tmp2 = (!((st).ncomments)) in
          (tok k (lexeme st i e') sp tmp1 tmp2))))
        | RUOperator -> (let id = (s ()) in
          (match (FStarC_PSMap.try_find uoperators id) with
            | (Some ((k, t))) -> (finish k t)
            | None -> (finish FStarC_Parser_TokenKind.OPINFIX4 id)
          ))
        | (RMixfix (k)) -> (let tmp1 = (s ()) in
          (finish k tmp1))
        | REof -> (let tmp1 = (!((st).ncomments)) in
          (tok FStarC_Parser_TokenKind.EOF "" sp sp tmp1))
        | RAny -> (lex_error st FStarC_Errors_Codes.Fatal_SyntaxError "unexpected char" sp sp)
      ))
  ))))

let rec lex_all__go (st : lstate) (acc : (token) list) : (token) list =
  (let t = (try (next_token st) with
      | (LexFail ((code, msg, r))) -> (let p = (cur_pos st) in
        let tmp = (!((st).ncomments)) in
        let tmp1 = (tok FStarC_Parser_TokenKind.ERROR msg p p tmp) in
        { kind = (tmp1).kind;
          text = (tmp1).text;
          sp = (tmp1).sp;
          ep = (tmp1).ep;
          extra = (LexError (code, msg, r));
          ncom = (tmp1).ncom })
    ) in
  (if (((=) (t).kind FStarC_Parser_TokenKind.EOF) || ((=) (t).kind FStarC_Parser_TokenKind.ERROR)) then (BatList.rev (t :: acc)) else ((lex_all__go st) (t :: acc))))

let lex_all (fname : string) (contents : string) (line : Prims.int) (col : Prims.int) : ((token) list * ((string * FStarC_Range_Type.range)) list) =
  (let tmp = (ref 0) in
