  let tmp2 = (ref 0) in
  let tmp3 = (ref (FStarC_SmallInt.of_int col)) in
  let tmp4 = (ref 0) in
  let tmp5 = (ref (FStarC_SmallInt.of_int col)) in
  let tmp6 = (ref []) in
  let tmp7 = (ref 0) in
  let st = { buf = contents;
      len = (String.length contents);
      fname = fname;
      cur = tmp;
      lnum = tmp1;
      bol = tmp2;
      bol_col = tmp3;
      cache_off = tmp4;
      cache_col = tmp5;
      comments = tmp6;
      ncomments = tmp7 } in
